 $('profile-form').addEventListener('submit',e=>{e.preventDefault();execute(e.submitter,async()=>{session.assert();if(!e.target.reportValidity())return;const fields={};document.querySelectorAll('[data-field]').forEach(el=>fields[el.dataset.field]=el.value.trim());const next={...profile};if(moduleName==='mini_profile_v1'){for(const [from,to] of Object.entries(miniToMature))next[from]=fields[to];next.dominantHand=({D:'Derecha',I:'Izquierda',A:'Uso ambas manos'})[fields.mano]||'';}else Object.assign(next,fields);next.technicalAreas=[...document.querySelectorAll('#technical-preferences input:checked')].map(el=>el.value);next.areas=next.technicalAreas;next.mentalAreas=[...document.querySelectorAll('#mental-preferences input:checked')].map(el=>el.value);const season=String(new Date().getFullYear());next.position=fields.position;next.dream=fields.dream;next.seasonGoal=fields.seasonGoal;next.seasonGoalSeason=season;next.seasonGoals={...(profile.seasonGoal?{[profile.seasonGoalSeason||'2026']:profile.seasonGoal}:{}),...profile.seasonGoals,[season]:fields.seasonGoal};await NextLevelData.saveModule(client,session,player.id,moduleName,next);profile=next;modules.set(moduleName,next);renderGoals();status('Perfil guardado en Supabase.');});});
 $('practice-form').addEventListener('submit',e=>{e.preventDefault();execute(e.submitter,async()=>{session.assert();const date=$('practice-date').value;const success=$('practice-success').value.trim(),area=$('practice-area').value.trim();const areas=[...document.querySelectorAll('[data-practice-area]:checked')].map(el=>el.value);if(area&&!areas.includes(area))areas.push(area);if(!dateValid(date)||!success||!areas.length)throw Error('Revisá la fecha y completá tu práctica.');const entry={id:crypto.randomUUID(),date,areas,success,next:$('practice-next').value.trim(),source:'player_training',createdAt:new Date().toISOString()};const made=$('shot-made').value,attempts=$('shot-attempts').value;if(made!==''||attempts!==''){const m=Number(made),a=Number(attempts);if(made===''||attempts===''||!Number.isInteger(m)||!Number.isInteger(a)||m<0||a<1||a>1000||m>a)throw Error('Revisá los tiros: convertidos no puede superar intentados (1 a 1000).');entry.shots={type:$('shot-type').value,made:m,attempts:a};}await NextLevelData.saveModule(client,session,player.id,'plan_progress_v1:'+entry.id,entry);practices.push(entry);practiceSummary();$('shot-made').value=$('shot-attempts').value='';showValue(node('article',null,$('practices')),entry);$('practice-success').value=$('practice-next').value='';status('Práctica guardada en Supabase.');});});
 $('photo-input').addEventListener('change',e=>execute($('photo-input'),async()=>{const file=e.target.files?.[0];if(!file)return;try{session.assert();if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Elegí una foto JPG, PNG o WebP de hasta 5 MB.');const image=await createImageBitmap(file);const scale=Math.min(1,640/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();const value=canvas.toDataURL('image/jpeg',.82);if(value.length>750000)throw Error('Elegí una foto más pequeña.');session.assert();await NextLevelData.saveModule(client,session,player.id,'foto_url',value);photo(value);status('Foto guardada en tu perfil privado.');}finally{e.target.value='';}}));
